SELECT * FROM customer_data;

-- q1 what is total revenue generated by male and female customes?
select gender , sum(purchase_amount) as total_revenue 
from customer_data group by gender;

--q2  which customer is used a discount but still spen more that the averae purchase amount?
select customer_id , purchase_amount from customer_data where discount_applied = 'Yes' 
and purchase_amount >= (select avg(purchase_amount) from customer_data);

--q3 Which are the top 5 products with the highest average review rating?

SELECT
    "item_purchased",
    ROUND(AVG("review_rating")::numeric, 2) AS avg_review_rating
FROM customer_data
GROUP BY "item_purchased"
ORDER BY avg_review_rating DESC
LIMIT 5;

--Q4. Compare the average Purchase Amounts between Standard and Express Shipping.

SELECT
    "shipping_type",
    ROUND(AVG("purchase_amount")::numeric, 2) AS avg_purchase_amount
FROM customer_data
WHERE "shipping_type" IN ('Standard', 'Express')
GROUP BY "shipping_type"
ORDER BY avg_purchase_amount DESC;

-- Q5: Compare subscribers vs non-subscribers

SELECT
    "subscription_status",
    ROUND(AVG("purchase_amount")::numeric, 2) AS avg_spend,
    SUM("purchase_amount") AS total_revenue,
    COUNT(*) AS total_customers
FROM customer_data
GROUP BY "subscription_status"
ORDER BY avg_spend DESC;

--q6  Which 5 products have the highest percentage of purchases with discounts applied?
SELECT
    item_purchased,
    ROUND(
        100.0 * COUNT(*) FILTER (
            WHERE LOWER(discount_applied) = 'yes'
        ) / COUNT(*), 2
    ) AS discount_percentage
FROM customer_data
GROUP BY item_purchased
ORDER BY discount_percentage DESC
LIMIT 5;

--Q7 Segment customers into New, Returning, and Loyal based on their total number of previous purchases, and show the count of each segement
SELECT
    CASE
        WHEN "previous_purchases" = 0 THEN 'New'
        WHEN "previous_purchases" BETWEEN 1 AND 5 THEN 'Returning'
        ELSE 'Loyal'
    END AS customer_segment,
    COUNT(*) AS customer_count
FROM customer_data
GROUP BY customer_segment
ORDER BY customer_count DESC;

--Q8 -- Top 3 products within each category
WITH product_counts AS (
    SELECT
        category,
        item_purchased,
        COUNT(*) AS total_purchases,
        ROW_NUMBER() OVER (
            PARTITION BY category
            ORDER BY COUNT(*) DESC
        ) AS rank
    FROM customer_data
    GROUP BY category, item_purchased
)
SELECT *
FROM product_counts
WHERE rank <= 3
ORDER BY category, rank;

-- Q9 Are customers who are repeat buyers (more than 5 previous purchases) also likely to subscribe?
SELECT
    CASE
        WHEN previous_purchases > 5 THEN 'Repeat Buyer'
        ELSE 'Other Customers'
    END AS customer_type,
    COUNT(*) AS total_customers,
    COUNT(*) FILTER (
        WHERE LOWER(subscription_status) = 'yes'
    ) AS subscribers,
    ROUND(
        100.0 * COUNT(*) FILTER (
            WHERE LOWER(subscription_status) = 'yes'
        ) / COUNT(*), 2
    ) AS subscription_percentage
FROM customer_data
GROUP BY customer_type;

--Q10 What is the revenue contribution of each age group

SELECT
    age_group,
    SUM(purchase_amount) AS total_revenue
	from customer_data 	group by age_group
	order by total_revenue desc ;